export function localizeService(service: Service, language: Language): Service {
  return language === 'en' ? service : { ...service, ...(serviceCopy[language][service.id] ?? {}) };
}

export function localizeNews(item: NewsItem, language: Language): NewsItem {
  return language === 'en' ? item : { ...item, ...(newsCopy[language][item.id] ?? {}) } as NewsItem;
}

export function localizeDocument(document: Document, language: Language): Document {
  if (language === 'en') return document;
  const key = document.id === 'doc-009' ? 'pan' : document.id === 'doc-010' ? 'licence' : document.type;
  return { ...document, name: documentNames[language][key] ?? document.name };
}

export function localizeNotification(notification: Notification, language: Language): Notification {
  return language === 'en' ? notification : { ...notification, ...(notificationCopy[language][notification.id] ?? {}) };
}

