export function localizeApplication(application: Application, language: Language, service?: Service): Application {
  if (language === 'en') return application;
  const copy = timelineCopy[language];
  return {
    ...application,
    serviceTitle: service ? localizeService(service, language).title : application.serviceTitle,
    timeline: application.timeline.map((step) => {
      const translated = copy[step.id];
      return translated ? { ...step, label: translated[0], description: translated[1] } : step;
    }),
  };
}


